// frontend/src/components/UserProfile/UserProfile.js
import React, { useState, useEffect, useCallback } from 'react';
import { usersApi, paymentApi } from '../../services/api';
import './UserProfile.css';

const UserProfile = () => {
  const [profile, setProfile] = useState(null);
  const [subscription, setSubscription] = useState(null);
  const [qrCode, setQrCode] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // Загрузка профиля и подписки
  const loadProfile = useCallback(async () => {
    try {
      setLoading(true);
      const [profileRes, subRes] = await Promise.all([
        usersApi.getCurrentUser(),
        paymentApi.getCurrentSubscription()
      ]);
      setProfile(profileRes.data);
      setSubscription(subRes.data);
      setError(null);
    } catch (err) {
      console.error('Ошибка загрузки профиля:', err);
      setError('Не удалось загрузить профиль');
    } finally {
      setLoading(false);
    }
  }, []);

  // Создание платежа (SBP QR)
  const handleCreatePayment = async (tier) => {
    try {
      const response = await paymentApi.createPayment({
        amount: tier === 'premium' ? 990 : 490,
        description: `Подписка ${tier}`,
        tier
      });
      setQrCode(response.data.qrCode);
      alert('QR-код сгенерирован! Оплатите по СБП');
    } catch (err) {
      alert('Не удалось создать платёж');
    }
  };

  // Проверка статуса платежа (поллинг)
  useEffect(() => {
    loadProfile();

    const interval = setInterval(() => {
      if (subscription?.status === 'pending') loadProfile();
    }, 5000);

    return () => clearInterval(interval);
  }, [loadProfile, subscription]);

  if (loading) return <div className="loading">Загрузка профиля...</div>;
  if (error) return <div className="error">{error}</div>;

  return (
    <div className="user-profile">
      <h2>Мой профиль</h2>
      {profile && (
        <>
          <p><strong>Имя:</strong> {profile.username || profile.name}</p>
          <p><strong>Email:</strong> {profile.email}</p>
          <p><strong>Роль:</strong> {profile.role || profile.roles?.join(', ')}</p>
        </>
      )}

      <h3>Подписка</h3>
      {subscription ? (
        <div className="subscription-card">
          <p>Статус: <strong>{subscription.status}</strong></p>
          <p>Тариф: {subscription.tier}</p>
          <p>До: {subscription.expiresAt ? new Date(subscription.expiresAt).toLocaleDateString('ru-RU') : '—'}</p>
        </div>
      ) : (
        <p>Подписки нет</p>
      )}

      <h3>Оформить подписку</h3>
      <button onClick={() => handleCreatePayment('basic')}>Базовая — 490 ₽</button>
      <button onClick={() => handleCreatePayment('premium')}>Премиум — 990 ₽</button>

      {qrCode && (
        <div className="qr-section">
          <img src={qrCode} alt="SBP QR" />
          <p>Отсканируйте для оплаты</p>
        </div>
      )}
    </div>
  );
};

export default UserProfile;
